# We'll build a mapping from song_id to its title and artists for easy lookup.

unique_song_ids = set()
for playlist in all_playlists:
    unique_song_ids.update(playlist["song_ids"])

song_id_to_metadata = {}
for song_id in unique_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if song and "song_id" in song:
        song_id_to_metadata[song_id] = {
            "title": song["title"],
            "artists": [artist["name"] for artist in song["artists"]]
        }

print(song_id_to_metadata)  # Mapping from song_id to {"title": ..., "artists": [...]}

