# Now, let's identify which song_ids in each playlist correspond to the old_songs list.
# We'll match by both title and all artists (order-insensitive).
# We'll build a set of song_ids to archive, and a mapping from playlist_id to the list of song_ids to remove from that playlist.

def song_matches(song_meta, old_song):
    # Compare title (case-insensitive, trimmed) and set of artists (case-insensitive, trimmed)
    return (
        song_meta["title"].strip().lower() == old_song["title"].strip().lower() and
        set(a.strip().lower() for a in song_meta["artists"]) == set(a.strip().lower() for a in old_song["artists"])
    )

# Build set of song_ids to archive
song_ids_to_archive = set()
for song_id, meta in song_id_to_metadata.items():
    for old_song in old_songs:
        if song_matches(meta, old_song):
            song_ids_to_archive.add(int(song_id))

# Build mapping from playlist_id to list of song_ids to remove
playlist_removals = {}
for playlist in all_playlists:
    to_remove = [sid for sid in playlist["song_ids"] if sid in song_ids_to_archive]
    if to_remove:
        playlist_removals[playlist["playlist_id"]] = to_remove

print("song_ids_to_archive:", song_ids_to_archive)
print("playlist_removals:", playlist_removals)  # playlist_id -> list of song_ids to remove from that playlist

